<?php
namespace App\Controllers;
use App\Core\{Auth,Database,HttpException};
final class MediaController {
 public function show(string $folder,string $name): void {if(!in_array($folder,['profiles','questions','tests'],true)||!preg_match('/^[a-f0-9]{32}\.webp$/',$name))throw new HttpException(404,'Image not found.');$relative=$folder.'/'.$name;$db=Database::connection();if($folder==='tests'){$q=$db->prepare("SELECT COUNT(*) FROM tests WHERE thumbnail_path=? AND status='published' AND deleted_at IS NULL");$q->execute([$relative]);if((int)$q->fetchColumn()){$path=dirname(__DIR__,2).'/storage/uploads/'.$relative;if(!is_file($path))throw new HttpException(404,'Image not found.');header('Content-Type: image/webp');header('Cache-Control: public, max-age=86400');header('X-Content-Type-Options: nosniff');readfile($path);return;}}$user=Auth::require();if($folder==='profiles'&&$user['role']!=='admin'&&!hash_equals((string)($user['profile_photo']??''),$relative))throw new HttpException(403,'You do not have permission to view this image.');if($folder==='tests'&&$user['role']!=='admin')throw new HttpException(403,'You do not have permission to view this image.');if($folder==='questions'&&$user['role']!=='admin'){$q=$db->prepare("SELECT COUNT(*) FROM questions q JOIN tests t ON t.id=q.test_id JOIN enrollments e ON e.test_id=t.id AND e.student_id=? AND e.status='active' WHERE q.image_path=? OR EXISTS(SELECT 1 FROM question_options qo WHERE qo.question_id=q.id AND qo.image_path=?)");$q->execute([Auth::id(),$relative,$relative]);if(!(int)$q->fetchColumn())throw new HttpException(403,'You do not have permission to view this image.');}$path=dirname(__DIR__,2).'/storage/uploads/'.$relative;if(!is_file($path))throw new HttpException(404,'Image not found.');header('Content-Type: image/webp');header('Cache-Control: private, max-age=86400');header('X-Content-Type-Options: nosniff');readfile($path);}
}
